using System.Text;
using Microsoft.CodeAnalysis.Testing;
using Microsoft.CodeAnalysis.Text;

namespace AnalyserAttributeProxyGenerator.Tests
{
    internal static class SourceFileCollectionExtensions
    {
        private const string EmbeddedAttributeSource =
"""
// <auto-generated/>
namespace Microsoft.CodeAnalysis
{
    internal sealed partial class EmbeddedAttribute : global::System.Attribute
    {
    }
}
""";

        public static void AddEmbeddedAttribute<TGenerator>(this SourceFileCollection sourceFileCollection)
            => sourceFileCollection.Add((typeof(TGenerator), "Microsoft.CodeAnalysis.EmbeddedAttribute.cs", SourceText.From(EmbeddedAttributeSource, Encoding.UTF8)));
    }
}
